// "cache-version" is replaced by a hash generated by vite.config.mjs
const CACHE_NAME = 'storyline-cache-v-cache-version';
const NAVIGATION_TIMEOUT = 3000;

const URLS_TO_CACHE = [
    '/',
    '/tracker/',
    'build-files',
    '/manifest.json',
    '/fonts/PirataOne-Regular.woff2',
    '/fonts/Nyala-Regular.woff2',
    '/fonts/Moyenage.woff2',
    '/fonts/MaterialSymbols.woff2',
    '/fonts/ArialMT.woff2',
    '/android-chrome-72x72.png',
    '/apple-touch-icon.png'
];

// Lazy language chunks, cached when used.
const LANGUAGE_FILES = [
    'language-files',
];

self.addEventListener('install', event => {
    // Activate right away: pages are fetched from the network first, so open tabs don't depend on the previous cache.
    self.skipWaiting();
    event.waitUntil(
        caches.open(CACHE_NAME)
            // Bypass the HTTP cache, so a new worker doesn't precache the previous build's pages.
            .then(cache => cache.addAll(URLS_TO_CACHE.map(url => new Request(url, {cache: 'reload'}))))
    );
});

self.addEventListener('activate', event => {
    event.waitUntil((async () => {
        const cache = await caches.open(CACHE_NAME);
        for (const cacheName of (await caches.keys()).filter(cacheName => cacheName !== CACHE_NAME)) {
            // Keep the cached languages this build still uses, otherwise they'd fall back to English when offline.
            const oldCache = await caches.open(cacheName);
            for (const url of LANGUAGE_FILES) {
                const response = await oldCache.match(url);
                if (response) {
                    await cache.put(url, response);
                }
            }
            await caches.delete(cacheName);
        }
        await self.clients.claim();
    })());
});

self.addEventListener('fetch', event => {
    const request = event.request;
    const url = new URL(request.url);
    if (request.method !== 'GET' || url.origin !== self.location.origin) {
        return;
    }

    // Network first, so a deploy shows up on the next load. Offline or on a slow connection, fall back to the
    // precached page of this build.
    if (request.mode === 'navigate') {
        const cached = () => caches.match(url.pathname.startsWith('/tracker') ? '/tracker/' : '/');
        const network = fetch(request);
        const timeout = new Promise(resolve => setTimeout(resolve, NAVIGATION_TIMEOUT));
        event.respondWith(
            Promise.race([network, timeout.then(cached)])
                .then(response => response || network)
                .catch(() => cached().then(response => response || network))
        );
        return;
    }

    // API calls (fetch/xhr) have no destination: never serve those from the cache.
    if (request.destination === '') {
        return;
    }

    event.respondWith(
        caches.match(request).then(cached => cached || fetch(request).then(response => {
            if (response.ok && response.type === 'basic') {
                const copy = response.clone();
                caches.open(CACHE_NAME).then(cache => cache.put(request, copy));
            }
            return response;
        }))
    );
});
